function useStored<T>(key: string, initial: T) {
  const [value, setValue] = useState<T>(() => { try { const saved = localStorage.getItem(key); return saved ? JSON.parse(saved) as T : initial; } catch { return initial; } });
  useEffect(() => { try { localStorage.setItem(key, JSON.stringify(value)); } catch { /* Keep the app usable if storage is unavailable. */ } }, [key, value]);
  return [value, setValue] as const;
}

function FinancialBackground() {
  const mount = useRef<HTMLDivElement>(null);
  const [fallback, setFallback] = useState(false);
  useEffect(() => {
    const holder = mount.current; if (!holder) return;
    let renderer: THREE.WebGLRenderer;
    try { renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true, powerPreference: 'low-power' }); } catch { setFallback(true); return; }
    const mobile = window.innerWidth < 768;
    const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, mobile ? 1 : 1.5)); renderer.setSize(holder.clientWidth, holder.clientHeight); renderer.setClearColor(0x000000, 0); holder.appendChild(renderer.domElement);
    const scene = new THREE.Scene(); const camera = new THREE.PerspectiveCamera(42, holder.clientWidth / holder.clientHeight, 0.1, 100); camera.position.set(0, 0, 15);
    scene.add(new THREE.AmbientLight(0xffffff, 1.7)); const light = new THREE.PointLight(0xc4ff8e, 65, 30); light.position.set(3, 5, 9); scene.add(light);
    const group = new THREE.Group(); scene.add(group);
    const coinMaterial = new THREE.MeshStandardMaterial({ color: 0xb1dc78, metalness: 0.75, roughness: 0.28, emissive: 0x385526, emissiveIntensity: 0.3 });
    const edgeMaterial = new THREE.MeshStandardMaterial({ color: 0x698c51, metalness: 0.8, roughness: 0.26 });
    const coinPositions = mobile ? [[1.5, 0.1, 0]] : [[1.5, 0.35, 0], [-2.5, 1.35, -2], [3.7, -1.6, -3], [-1.2, -2.5, -4]];
    const coins: THREE.Group[] = [];
    coinPositions.forEach(([x, y, z], i) => {
      const coin = new THREE.Group(); const radius = i === 0 ? 1.28 : 0.48;
      const disc = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, 0.16, 64), coinMaterial); disc.rotation.x = Math.PI / 2; coin.add(disc);
      const ring = new THREE.Mesh(new THREE.TorusGeometry(radius * 0.81, 0.025, 8, 64), edgeMaterial); ring.position.z = 0.09; coin.add(ring);
      const inner = new THREE.Mesh(new THREE.TorusGeometry(radius * 0.66, 0.012, 6, 64), edgeMaterial); inner.position.z = 0.095; coin.add(inner);
      const canvas = document.createElement('canvas'); canvas.width = canvas.height = 256; const ctx = canvas.getContext('2d');
      if (ctx) { ctx.fillStyle = '#314b2c'; ctx.font = 'bold 140px Georgia'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.fillText(i === 0 ? '$' : '%', 128, 133); }
      const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: new THREE.CanvasTexture(canvas), transparent: true })); sprite.scale.set(radius * 1.2, radius * 1.2, 1); sprite.position.z = 0.12; coin.add(sprite);
      coin.position.set(x, y, z); coin.rotation.y = -0.4 + i * 0.3; coin.rotation.x = -0.2; group.add(coin); coins.push(coin);
    });
    const points = Array.from({ length: 14 }, (_, i) => new THREE.Vector3(-5.2 + i * 0.78, -1.85 + i * 0.2 + Math.sin(i * 1.8) * 0.3, -3.5));
    group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(points), new THREE.LineBasicMaterial({ color: 0xa7ef77, transparent: true, opacity: 0.65 })));
    points.filter((_, i) => i % 3 === 0).forEach(p => { const dot = new THREE.Mesh(new THREE.SphereGeometry(0.055, 8, 8), new THREE.MeshBasicMaterial({ color: 0xd4ffab })); dot.position.copy(p); group.add(dot); });
    const count = mobile ? 26 : 85; const positions = new Float32Array(count * 3);
    for (let i = 0; i < count; i++) { positions[i * 3] = (Math.random() - 0.5) * 13; positions[i * 3 + 1] = (Math.random() - 0.5) * 8; positions[i * 3 + 2] = -2 - Math.random() * 5; }
    const particles = new THREE.BufferGeometry(); particles.setAttribute('position', new THREE.BufferAttribute(positions, 3)); group.add(new THREE.Points(particles, new THREE.PointsMaterial({ color: 0xb7f078, size: 0.035, transparent: true, opacity: 0.55 })));
    if (!mobile) { const shape = new THREE.Mesh(new THREE.IcosahedronGeometry(0.7, 0), new THREE.MeshBasicMaterial({ color: 0x83b85e, wireframe: true, transparent: true, opacity: 0.2 })); shape.position.set(-3.7, -0.5, -4); group.add(shape); const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints([shape.position, ...points.filter((_, i) => i % 3 === 0).slice(0, 3), new THREE.Vector3(-2.5, 1.35, -2)]), new THREE.LineBasicMaterial({ color: 0x9ed46d, transparent: true, opacity: 0.22 })); group.add(line); }
    let mx = 0, my = 0, frame = 0; const clock = new THREE.Clock();
    const onMouse = (e: MouseEvent) => { mx = (e.clientX / window.innerWidth - 0.5) * 0.35; my = (e.clientY / window.innerHeight - 0.5) * 0.25; };
    const onResize = () => { if (!holder.clientWidth || !holder.clientHeight) return; camera.aspect = holder.clientWidth / holder.clientHeight; camera.updateProjectionMatrix(); renderer.setSize(holder.clientWidth, holder.clientHeight); };
    window.addEventListener('mousemove', onMouse); window.addEventListener('resize', onResize);
    const animate = () => { frame = requestAnimationFrame(animate); const t = clock.getElapsedTime(); if (!reduced) { group.rotation.y += (mx - group.rotation.y) * 0.025; group.rotation.x += (-my - group.rotation.x) * 0.025; coins.forEach((c, i) => { c.position.y = coinPositions[i][1] + Math.sin(t * 0.8 + i * 1.6) * 0.12; c.rotation.y += 0.002; }); } renderer.render(scene, camera); }; animate();
    return () => { cancelAnimationFrame(frame); window.removeEventListener('mousemove', onMouse); window.removeEventListener('resize', onResize); holder.removeChild(renderer.domElement); scene.traverse(obj => { if (obj instanceof THREE.Mesh || obj instanceof THREE.Points || obj instanceof THREE.Line) { obj.geometry.dispose(); const mats = Array.isArray(obj.material) ? obj.material : [obj.material]; mats.forEach(m => m.dispose()); } if (obj instanceof THREE.Sprite) { obj.material.map?.dispose(); obj.material.dispose(); } }); renderer.dispose(); };
  }, []);
  return <div ref={mount} className={`financial-background ${fallback ? 'financial-fallback' : ''}`} aria-hidden="true" />;
}

function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: ReactNode }) {
  useEffect(() => { const key = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose(); }; window.addEventListener('keydown', key); return () => window.removeEventListener('keydown', key); }, [onClose]);
  return <div className="modal-backdrop" onMouseDown={e => { if (e.target === e.currentTarget) onClose(); }}><div className="modal-panel" role="dialog" aria-modal="true" aria-label={title}><div className="modal-head"><h2>{title}</h2><button className="icon-btn" onClick={onClose} aria-label="Close dialog"><X size={19} /></button></div>{children}</div></div>;
}
function EmptyState({ icon, title, text, action }: { icon: ReactNode; title: string; text: string; action?: ReactNode }) { return <div className="empty-state"><div className="empty-icon">{icon}</div><h3>{title}</h3><p>{text}</p>{action}</div>; }

function App() {
  const [investments, setInvestments] = useStored<Investment[]>('investsphere-investments', seedInvestments);
  const [transactions, setTransactions] = useStored<Transaction[]>('investsphere-transactions', seedTransactions);
  const [goals, setGoals] = useStored<Goal[]>('investsphere-goals', seedGoals);
  const [watchlist, setWatchlist] = useStored<string[]>('investsphere-watchlist', ['MSFT', 'TSLA', 'ETH', 'AMZN']);
  const [page, setPage] = useState<Page>('Dashboard'); const [modal, setModal] = useState<'investment' | 'transaction' | 'goal' | 'watchlist' | null>(null);
  const [editing, setEditing] = useState<Investment | Goal | null>(null); const [toast, setToast] = useState(''); const [mobileNav, setMobileNav] = useState(false);
  const [range, setRange] = useState<typeof ranges[number]>('1Y'); const [search, setSearch] = useState(''); const [filter, setFilter] = useState('All assets'); const [sort, setSort] = useState('Value: high to low');
  const [chatInput, setChatInput] = useState(''); const [messages, setMessages] = useState<ChatMessage[]>([{ role: 'assistant', text: 'Hi! I can help you understand your portfolio. Ask me about performance, allocation, or your best-performing asset.' }]); const [thinking, setThinking] = useState(false); const chatEnd = useRef<HTMLDivElement>(null);
  useEffect(() => { if (toast) { const timer = setTimeout(() => setToast(''), 3500); return () => clearTimeout(timer); } }, [toast]);
  useEffect(() => { chatEnd.current?.scrollIntoView({ behavior: 'smooth', block: 'nearest' }); }, [messages, thinking]);
  const totals = useMemo(() => { const invested = investments.reduce((s, a) => s + a.quantity * a.buyPrice, 0); const value = investments.reduce((s, a) => s + a.quantity * a.currentPrice, 0); const daily = investments.reduce((s, a) => s + a.quantity * a.currentPrice * a.dailyChange / (100 + a.dailyChange), 0); return { invested, value, profit: value - invested, daily, returnPct: invested ? (value - invested) / invested * 100 : 0, dailyPct: value - daily ? daily / (value - daily) * 100 : 0 }; }, [investments]);
  const allocation = useMemo(() => assetTypes.map(type => ({ name: type, value: investments.filter(a => a.type === type).reduce((s, a) => s + a.quantity * a.currentPrice, 0), color: colors[type] })).filter(a => a.value > 0).sort((a, b) => b.value - a.value), [investments]);
  const sortedInvestments = useMemo(() => investments.filter(a => a.name.toLowerCase().includes(search.toLowerCase()) && (filter === 'All assets' || a.type === filter)).sort((a, b) => { if (sort === 'Name: A to Z') return a.name.localeCompare(b.name); if (sort === 'Return: high to low') return (b.currentPrice / b.buyPrice) - (a.currentPrice / a.buyPrice); if (sort === 'Value: low to high') return (a.quantity * a.currentPrice) - (b.quantity * b.currentPrice); return (b.quantity * b.currentPrice) - (a.quantity * a.currentPrice); }), [investments, search, filter, sort]);
  const performance = useMemo(() => { const count = range === '1D' ? 16 : range === '1W' ? 7 : range === '1M' ? 30 : range === '6M' ? 26 : range === '1Y' ? 36 : range === '5Y' ? 48 : 60; const growth = ({ '1D': 0.009, '1W': 0.025, '1M': 0.055, '6M': 0.17, '1Y': 0.32, '5Y': 0.67, All: 0.86 } as Record<string, number>)[range]; return Array.from({ length: count }, (_, i) => { const p = i / (count - 1); const wave = Math.sin(i * 1.7) * 0.016 + Math.sin(i * 0.64 + 1.2) * 0.021; const value = i === count - 1 ? totals.value : Math.max(0, totals.value * (1 - growth * (1 - p) + wave * (1 - p))); let label = ''; if (range === '1D') label = `${8 + Math.floor(i * 0.7)}:00`; else if (range === '1W') label = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'][i]; else if (range === '1M') label = `${i + 1}`; else { const d = new Date(); d.setMonth(d.getMonth() - Math.round((count - 1 - i) * (range === '6M' ? 6 : range === '1Y' ? 12 : range === '5Y' ? 60 : 84) / (count - 1))); label = d.toLocaleDateString('en-US', { month: 'short', year: range === '5Y' || range === 'All' ? '2-digit' : undefined }); } return { label, value: Math.round(value * 100) / 100 }; }); }, [range, totals.value]);
  const topAsset = [...investments].sort((a, b) => (b.currentPrice / b.buyPrice) - (a.currentPrice / a.buyPrice))[0]; const concentrated = investments.length ? [...investments].sort((a, b) => b.quantity * b.currentPrice - a.quantity * a.currentPrice)[0] : null; const concentrationPct = concentrated && totals.value ? concentrated.quantity * concentrated.currentPrice / totals.value * 100 : 0;
  const cashBalance = transactions.reduce((s, t) => s + (t.type === 'Deposit' || t.type === 'Dividend' || t.type === 'Sell' ? t.amount : -t.amount), 0);
  const notify = (text: string) => setToast(text); const navigate = (p: Page) => { setPage(p); setMobileNav(false); window.scrollTo({ top: 0, behavior: 'smooth' }); }; const openInvestment = (item?: Investment) => { setEditing(item || null); setModal('investment'); }; const openGoal = (item?: Goal) => { setEditing(item || null); setModal('goal'); }; const closeModal = () => { setModal(null); setEditing(null); };
  const removeInvestment = (id: string) => { if (window.confirm('Delete this investment? This cannot be undone.')) { setInvestments(prev => prev.filter(a => a.id !== id)); notify('Investment deleted'); } }; const removeGoal = (id: string) => { if (window.confirm('Delete this goal?')) { setGoals(prev => prev.filter(g => g.id !== id)); notify('Goal deleted'); } };
  const exportData = () => { const data = { investments, transactions, goals, watchlist, exportedAt: new Date().toISOString() }; const url = URL.createObjectURL(new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' })); const a = document.createElement('a'); a.href = url; a.download = 'investsphere-data.json'; a.click(); URL.revokeObjectURL(url); notify('Your data has been exported'); };
  const resetData = () => { if (window.confirm('Reset all investments, transactions, goals and watchlist to demo data?')) { setInvestments(seedInvestments); setTransactions(seedTransactions); setGoals(seedGoals); setWatchlist(['MSFT', 'TSLA', 'ETH', 'AMZN']); notify('Demo data restored'); } };
  const answerQuestion = (question: string) => { const q = question.toLowerCase(); if (!investments.length) return 'Your portfolio is empty right now. Add an investment to get personalized portfolio insights.'; if (/highest|best|top.perform|biggest return/.test(q)) return topAsset ? `${topAsset.name} has your highest return at ${percent((topAsset.currentPrice / topAsset.buyPrice - 1) * 100)}. Its current value is ${money(topAsset.quantity * topAsset.currentPrice)}.` : 'No assets are available yet.'; if (/allocat|diversif|breakdown|types/.test(q)) return `Your allocation is ${allocation.map(a => `${a.name} ${((a.value / totals.value) * 100).toFixed(1)}%`).join(', ')}. ${concentrationPct > 35 ? `${concentrated?.name} makes up ${concentrationPct.toFixed(1)}% of your portfolio, which may indicate concentration risk.` : 'No single holding exceeds 35% of your portfolio.'}`; if (/total invest|how much.*invest|cost basis/.test(q)) return `You have invested ${money(totals.invested)} across ${investments.length} holdings. Your portfolio is currently worth ${money(totals.value)}.`; if (/risk|concentrat|warning/.test(q)) return `${concentrationPct > 35 ? `${concentrated?.name} accounts for ${concentrationPct.toFixed(1)}% of your portfolio. ` : 'No single holding exceeds 35% of your portfolio. '}You hold ${allocation.length} asset types. Market prices in this demo are manually stored and may not reflect live prices.`; if (/goal/.test(q)) return goals.length ? `You have ${goals.length} active goals: ${goals.map(g => `${g.name} (${Math.min(100, g.current / g.target * 100).toFixed(0)}% complete)`).join(', ')}.` : 'You have no goals yet. Create one in the Goals section to start tracking progress.'; if (/today|daily/.test(q)) return `Based on stored demo daily changes, your portfolio is ${totals.daily >= 0 ? 'up' : 'down'} ${money(Math.abs(totals.daily))} (${percent(totals.dailyPct)}) today. These are not live market quotes.`; return `Your ${investments.length} holdings are worth ${money(totals.value)}, compared with ${money(totals.invested)} invested. That is ${totals.profit >= 0 ? 'a gain' : 'a loss'} of ${money(Math.abs(totals.profit))} (${percent(totals.returnPct)}). ${allocation.length} asset types are represented. This is based on your saved prices, not live market data.`; };
  const sendMessage = (text = chatInput) => { const q = text.trim(); if (!q || thinking) return; setMessages(prev => [...prev, { role: 'user', text: q }]); setChatInput(''); setThinking(true); setTimeout(() => { setMessages(prev => [...prev, { role: 'assistant', text: answerQuestion(q) }]); setThinking(false); }, 500); };
  const navItems: { name: Page; icon: ReactNode }[] = [{ name: 'Dashboard', icon: <LayoutDashboard size={19} /> }, { name: 'Portfolio', icon: <Wallet size={19} /> }, { name: 'Transactions', icon: <ArrowDownLeft size={19} /> }, { name: 'Watchlist', icon: <Eye size={19} /> }, { name: 'Goals', icon: <Target size={19} /> }, { name: 'AI Insights', icon: <Sparkles size={19} /> }];

  return <div className="app-shell">
    {mobileNav && <div className="mobile-scrim" onClick={() => setMobileNav(false)} />}
    <aside className={`sidebar ${mobileNav ? 'sidebar-open' : ''}`}><button className="brand" onClick={() => navigate('Dashboard')} aria-label="InvestSphere AI home"><span className="brand-mark"><Activity size={23} strokeWidth={2.4} /></span><span className="brand-text">InvestSphere <b>AI</b><small>INTELLIGENT INVESTING</small></span></button><div className="sidebar-label">WORKSPACE</div><nav className="side-nav" aria-label="Main navigation">{navItems.map(item => <button key={item.name} className={`nav-link ${page === item.name ? 'active' : ''}`} onClick={() => navigate(item.name)}>{item.icon}<span>{item.name}</span>{item.name === 'AI Insights' && <span className="nav-new">NEW</span>}</button>)}</nav><div className="sidebar-bottom"><div className="sidebar-label">PREFERENCES</div><button className={`nav-link ${page === 'Settings' ? 'active' : ''}`} onClick={() => navigate('Settings')}><Settings size={19} /><span>Settings</span></button><div className="sidebar-support"><div className="support-icon"><ShieldCheck size={18} /></div><div><strong>Your data stays yours</strong><span>Stored locally on this device.</span></div></div><div className="sidebar-profile"><div className="avatar">JD</div><div><strong>Jordan Davis</strong><span>Personal workspace</span></div><MoreHorizontal size={18} /></div></div></aside>
    <main className="main-area"><header className="topbar"><div className="topbar-left"><button className="mobile-menu icon-btn" onClick={() => setMobileNav(true)} aria-label="Open menu"><Menu size={22} /></button><span className="breadcrumb">Workspace</span><span className="breadcrumb-slash">/</span><span className="breadcrumb-current">{page}</span></div><div className="topbar-right"><span className="market-status"><span className="status-dot" /> DEMO DATA</span><span className="header-divider" /><span className="top-date">{new Date().toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' })}</span><span className="top-avatar">JD</span></div></header><div className="content">
      {page === 'Dashboard' && <><section className="dashboard-hero"><FinancialBackground /><div className="hero-content"><div className="eyebrow"><span className="eyebrow-line" /> YOUR FINANCIAL OVERVIEW</div><h1>Wealth looks better<br /><em>in perspective.</em></h1><p>Everything you own, all in one intelligent place.</p><button className="primary-btn hero-btn" onClick={() => openInvestment()}><Plus size={18} /> Add investment <ArrowRight size={17} /></button></div><div className="hero-bottom-label"><span className="hero-pulse" /> YOUR PORTFOLIO, REIMAGINED</div></section><div className="section-heading summary-heading"><div><div className="eyebrow muted-eyebrow">AT A GLANCE</div><h2>Portfolio overview</h2></div><span className="section-note">Based on your saved asset prices</span></div><div className="metric-grid"><Metric label="Total invested" value={money(totals.invested)} icon={<Wallet size={18} />} note="Your cost basis" /><Metric label="Current value" value={money(totals.value)} icon={<BarChart3 size={18} />} note="Across all holdings" accent /><Metric label="Total profit / loss" value={`${totals.profit >= 0 ? '+' : '-'}${money(Math.abs(totals.profit))}`} icon={<TrendingUp size={18} />} note={percent(totals.returnPct) + ' all time'} signed={totals.profit} /><Metric label="Today's change" value={`${totals.daily >= 0 ? '+' : '-'}${money(Math.abs(totals.daily))}`} icon={<Activity size={18} />} note={percent(totals.dailyPct) + ' today'} signed={totals.daily} /><Metric label="Overall return" value={percent(totals.returnPct)} icon={<Zap size={18} />} note="Since first investment" signed={totals.returnPct} /></div><div className="dashboard-grid"><section className="surface chart-surface"><div className="surface-head"><div><div className="eyebrow muted-eyebrow">THE BIG PICTURE</div><h3>Portfolio performance</h3></div><div className="range-selector" aria-label="Performance time range">{ranges.map(r => <button key={r} className={range === r ? 'selected' : ''} onClick={() => setRange(r)}>{r}</button>)}</div></div><div className="chart-caption"><strong>{money(totals.value)}</strong><span className={totals.profit >= 0 ? 'positive' : 'negative'}>{percent(totals.returnPct)} all time</span></div><PerformanceChart data={performance} /></section><section className="surface allocation-surface"><div className="surface-head"><div><div className="eyebrow muted-eyebrow">YOUR MIX</div><h3>Asset allocation</h3></div><button className="subtle-link" onClick={() => navigate('Portfolio')}>Details <ArrowRight size={14} /></button></div><AllocationChart allocation={allocation} total={totals.value} /></section></div><div className="dashboard-grid bottom-grid"><section className="surface holdings-surface"><div className="surface-head"><div><div className="eyebrow muted-eyebrow">WHAT YOU OWN</div><h3>Top holdings</h3></div><button className="subtle-link" onClick={() => navigate('Portfolio')}>View portfolio <ArrowRight size={14} /></button></div>{[...investments].sort((a, b) => b.quantity * b.currentPrice - a.quantity * a.currentPrice).slice(0, 4).map(a => <HoldingRow key={a.id} asset={a} />)}{!investments.length && <EmptyState icon={<Wallet />} title="No investments yet" text="Add your first investment to start tracking." action={<button className="primary-btn" onClick={() => openInvestment()}>Add investment</button>} />}</section><section className="surface insight-preview"><div className="insight-icon"><Sparkles size={22} /></div><div className="eyebrow muted-eyebrow">INVESTSPHERE INTELLIGENCE</div><h3>A clearer view of your money.</h3><p>{investments.length ? concentrationPct > 35 ? `${concentrated?.name} represents ${concentrationPct.toFixed(0)}% of your portfolio. Explore how concentration may affect your mix.` : `Your portfolio spans ${allocation.length} asset types. Explore what your holdings say about your allocation and performance.` : 'Add an investment to unlock personalized, data-based observations.'}</p><button className="outline-btn" onClick={() => navigate('AI Insights')}>Explore AI insights <ArrowRight size={16} /></button><small>AI-generated information only. This is not financial advice.</small></section></div></>}
      {page === 'Portfolio' && <><PageHeading eyebrow="YOUR INVESTMENTS" title="Portfolio" description="A complete picture of your holdings and how they're performing." action={<button className="primary-btn" onClick={() => openInvestment()}><Plus size={18} /> Add investment</button>} /><div className="portfolio-totals"><div><span>PORTFOLIO VALUE</span><strong>{money(totals.value)}</strong></div><div><span>TOTAL INVESTED</span><strong>{money(totals.invested)}</strong></div><div><span>PROFIT / LOSS</span><strong className={totals.profit >= 0 ? 'positive' : 'negative'}>{totals.profit >= 0 ? '+' : '-'}{money(Math.abs(totals.profit))}</strong></div><div><span>RETURN</span><strong className={totals.returnPct >= 0 ? 'positive' : 'negative'}>{percent(totals.returnPct)}</strong></div></div><section className="surface table-surface"><div className="table-toolbar"><div><h3>All investments <span className="count-badge">{investments.length}</span></h3><p>Manage your assets and keep prices up to date.</p></div><div className="toolbar-controls"><label className="search-field"><Search size={17} /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search assets..." aria-label="Search assets" /></label><select aria-label="Filter assets by type" value={filter} onChange={e => setFilter(e.target.value)}><option>All assets</option>{assetTypes.map(t => <option key={t}>{t}</option>)}</select><select aria-label="Sort investments" value={sort} onChange={e => setSort(e.target.value)}><option>Value: high to low</option><option>Value: low to high</option><option>Return: high to low</option><option>Name: A to Z</option></select></div></div><div className="table-scroll"><table><thead><tr><th>ASSET</th><th>TYPE</th><th>QUANTITY</th><th>INVESTED</th><th>CURRENT VALUE</th><th>PROFIT / LOSS</th><th>RETURN</th><th>ACTIONS</th></tr></thead><tbody>{sortedInvestments.map(a => { const profit = a.quantity * (a.currentPrice - a.buyPrice); const ret = (a.currentPrice / a.buyPrice - 1) * 100; return <tr key={a.id}><td><AssetIdentity name={a.name} type={a.type} subtitle={`Added ${dateLabel(a.date)}`} /></td><td><span className="type-tag">{a.type}</span></td><td>{a.quantity.toLocaleString('en-US', { maximumFractionDigits: 6 })}</td><td>{money(a.quantity * a.buyPrice)}</td><td className="strong-cell">{money(a.quantity * a.currentPrice)}</td><td className={profit >= 0 ? 'positive' : 'negative'}>{profit >= 0 ? '+' : '-'}{money(Math.abs(profit))}</td><td><span className={`return-tag ${ret >= 0 ? 'up' : 'down'}`}>{percent(ret)}</span></td><td><div className="row-actions"><button className="icon-btn" title="Edit investment" aria-label={`Edit ${a.name}`} onClick={() => openInvestment(a)}><Edit3 size={16} /></button><button className="icon-btn danger-hover" title="Delete investment" aria-label={`Delete ${a.name}`} onClick={() => removeInvestment(a.id)}><Trash2 size={16} /></button></div></td></tr>; })}</tbody></table></div>{!sortedInvestments.length && <EmptyState icon={<Search />} title={investments.length ? 'No matching assets' : 'Your portfolio starts here'} text={investments.length ? 'Try changing your search or filter.' : 'Add an investment to see it here.'} action={!investments.length && <button className="primary-btn" onClick={() => openInvestment()}>Add investment</button>} />}</section><p className="data-footnote"><CircleHelp size={15} /> Prices are manually entered and are not updated with live market data. Edit an investment to update its current price.</p></>}
      {page === 'Transactions' && <><PageHeading eyebrow="MONEY IN MOTION" title="Transactions" description="Keep a clear record of every move you make." action={<button className="primary-btn" onClick={() => setModal('transaction')}><Plus size={18} /> Record transaction</button>} /><div className="page-stat-band"><div><span>RECORDED TRANSACTIONS</span><strong>{transactions.length}</strong></div><div><span>BUY TRANSACTIONS</span><strong>{transactions.filter(t => t.type === 'Buy').length}</strong></div><div><span>NET RECORDED CASH FLOW</span><strong className={cashBalance >= 0 ? 'positive' : 'negative'}>{money(cashBalance)}</strong></div></div><section className="surface table-surface"><div className="surface-head padded-head"><div><div className="eyebrow muted-eyebrow">YOUR ACTIVITY</div><h3>Transaction history</h3></div></div><div className="table-scroll"><table><thead><tr><th>DATE</th><th>ASSET</th><th>TYPE</th><th>QUANTITY</th><th>PRICE</th><th>AMOUNT</th><th>ACTIONS</th></tr></thead><tbody>{[...transactions].sort((a, b) => b.date.localeCompare(a.date)).map(t => <tr key={t.id}><td>{dateLabel(t.date)}</td><td className="strong-cell">{t.asset}</td><td><span className={`transaction-type ${t.type.toLowerCase()}`}>{t.type === 'Buy' || t.type === 'Deposit' || t.type === 'Dividend' ? <ArrowDownLeft size={14} /> : <ArrowUpRight size={14} />}{t.type}</span></td><td>{t.quantity ? t.quantity.toLocaleString('en-US', { maximumFractionDigits: 6 }) : '-'}</td><td>{t.price ? money(t.price) : '-'}</td><td className="strong-cell">{money(t.amount)}</td><td><button className="icon-btn danger-hover" title="Delete transaction" aria-label={`Delete ${t.type} transaction for ${t.asset}`} onClick={() => { if (window.confirm('Delete this transaction record? Holdings will not be changed.')) { setTransactions(prev => prev.filter(x => x.id !== t.id)); notify('Transaction deleted'); } }}><Trash2 size={16} /></button></td></tr>)}</tbody></table></div>{!transactions.length && <EmptyState icon={<ArrowDownLeft />} title="No transactions recorded" text="Record a buy, sell, deposit, withdrawal, or dividend to see it here." action={<button className="primary-btn" onClick={() => setModal('transaction')}>Record transaction</button>} />}</section><p className="data-footnote"><CircleHelp size={15} /> New buy and sell transactions update matching portfolio holdings. Deleting a history record does not reverse a trade.</p></>}
      {page === 'Watchlist' && <><PageHeading eyebrow="KEEP AN EYE ON" title="Watchlist" description="Follow the assets you're curious about, all in one place." action={<button className="primary-btn" onClick={() => setModal('watchlist')}><Plus size={18} /> Add to watchlist</button>} /><div className="watchlist-note"><Activity size={17} /><span>Market preview</span> Prices and daily changes below are demo data, not live quotes.</div><section className="surface table-surface"><div className="surface-head padded-head"><div><div className="eyebrow muted-eyebrow">ON YOUR RADAR</div><h3>Watched assets <span className="count-badge">{watchlist.length}</span></h3></div></div><div className="table-scroll"><table><thead><tr><th>ASSET</th><th>ASSET TYPE</th><th>CURRENT PRICE</th><th>DAILY CHANGE</th><th>CHANGE %</th><th>ACTIONS</th></tr></thead><tbody>{watchlist.map(symbol => { const a = market.find(m => m.symbol === symbol); if (!a) return null; const dollarChange = a.price - a.price / (1 + a.change / 100); return <tr key={symbol}><td><AssetIdentity name={a.name} type={a.type} subtitle={a.symbol} /></td><td><span className="type-tag">{a.type}</span></td><td className="strong-cell">{money(a.price)}</td><td className={a.change >= 0 ? 'positive' : 'negative'}>{a.change >= 0 ? '+' : '-'}{money(Math.abs(dollarChange))}</td><td><span className={`return-tag ${a.change >= 0 ? 'up' : 'down'}`}>{percent(a.change)}</span></td><td><button className="icon-btn danger-hover" title="Remove from watchlist" aria-label={`Remove ${a.name} from watchlist`} onClick={() => { setWatchlist(prev => prev.filter(s => s !== symbol)); notify(`${a.name} removed from watchlist`); }}><Trash2 size={16} /></button></td></tr>; })}</tbody></table></div>{!watchlist.length && <EmptyState icon={<Eye />} title="Nothing on your radar yet" text="Add an asset to keep an eye on its demo market price." action={<button className="primary-btn" onClick={() => setModal('watchlist')}>Add asset</button>} />}</section></>}
      {page === 'Goals' && <><PageHeading eyebrow="BUILD TOWARD MORE" title="Investment goals" description="Make your next milestone feel a little closer." action={<button className="primary-btn" onClick={() => openGoal()}><Plus size={18} /> Create goal</button>} /><div className="goals-grid">{goals.map((g, index) => { const progress = Math.min(100, g.current / g.target * 100); return <section className="surface goal-item" key={g.id}><div className="goal-top"><div className={`goal-symbol goal-symbol-${index % 3}`}><Flag size={21} /></div><div className="row-actions"><button className="icon-btn" title="Edit goal" aria-label={`Edit ${g.name}`} onClick={() => openGoal(g)}><Edit3 size={16} /></button><button className="icon-btn danger-hover" title="Delete goal" aria-label={`Delete ${g.name}`} onClick={() => removeGoal(g.id)}><Trash2 size={16} /></button></div></div><div className="eyebrow muted-eyebrow">YOUR MILESTONE</div><h3>{g.name}</h3><div className="goal-amount"><strong>{money(g.current)}</strong><span>of {money(g.target)}</span></div><div className="progress-track"><div className="progress-fill" style={{ width: `${progress}%` }} /></div><div className="goal-meta"><span>{progress.toFixed(0)}% complete</span><span>Target: {dateLabel(g.date)}</span></div></section>; })}<button className="new-goal" onClick={() => openGoal()}><span><Plus size={24} /></span><strong>Create a new goal</strong><small>Give your investments a purpose.</small></button></div>{!goals.length && <p className="data-footnote">Set a target amount and date to track your progress here.</p>}</>}
      {page === 'AI Insights' && <><PageHeading eyebrow="THE INTELLIGENCE LAYER" title="AI insights" description="Thoughtful observations built from the portfolio data you save." /><div className="disclaimer"><ShieldCheck size={19} /><span><strong>AI-generated information only. This is not financial advice.</strong> Insights are rule-based, use your stored data, and do not predict future returns.</span></div><div className="insights-layout"><div className="insights-main"><section className="surface insight-summary"><div className="insight-summary-top"><div className="insight-icon"><Sparkles size={22} /></div><span className="insight-updated">BASED ON SAVED PORTFOLIO</span></div><div className="eyebrow muted-eyebrow">YOUR PORTFOLIO, EXPLAINED</div><h2>{investments.length ? totals.profit >= 0 ? 'Your portfolio is growing.' : 'Your portfolio is finding its footing.' : 'Your story starts with one investment.'}</h2><p>{investments.length ? `You have ${money(totals.invested)} invested across ${investments.length} holdings, now valued at ${money(totals.value)}. That's ${totals.profit >= 0 ? 'a gain' : 'a loss'} of ${money(Math.abs(totals.profit))}, or ${percent(totals.returnPct)} overall.` : 'Add an investment to see a personalized summary of performance, allocation and potential risks.'}</p></section><div className="insight-detail-grid"><InsightBlock icon={<Coins size={20} />} title="Asset allocation" text={allocation.length ? `Your holdings span ${allocation.length} asset ${allocation.length === 1 ? 'class' : 'classes'}. ${allocation[0].name} is your largest category at ${((allocation[0].value / totals.value) * 100).toFixed(1)}% of portfolio value.` : 'Add assets to see how your portfolio is distributed.'} /><InsightBlock icon={<Activity size={20} />} title="Performance summary" text={investments.length ? `${investments.filter(a => a.currentPrice >= a.buyPrice).length} of your ${investments.length} holdings are above their buy price. ${topAsset?.name} currently has the highest return at ${topAsset ? percent((topAsset.currentPrice / topAsset.buyPrice - 1) * 100) : '0%'}.` : 'Performance details will appear after you add holdings.'} /><InsightBlock icon={<BarChart3 size={20} />} title="Diversification" text={allocation.length >= 3 ? `Your portfolio includes ${allocation.length} asset types, which spreads exposure across different categories. Diversification does not eliminate risk.` : allocation.length ? `Your holdings cover ${allocation.length} asset ${allocation.length === 1 ? 'type' : 'types'}. A narrower mix may increase exposure to a single market segment.` : 'Add investments to assess your asset mix.'} /><InsightBlock icon={<ShieldCheck size={20} />} title="Risk indicators" text={investments.length ? `${concentrationPct > 35 ? `${concentrated?.name} represents ${concentrationPct.toFixed(1)}% of your total value, a potential concentration risk. ` : 'No single asset exceeds 35% of portfolio value. '}Saved prices may be outdated, so returns may differ from current market values.` : 'Risk observations will appear when you add holdings.'} /></div></div><div className="insights-side"><section className="surface insight-allocation"><div className="eyebrow muted-eyebrow">COMPOSITION</div><h3>Allocation breakdown</h3><AllocationChart allocation={allocation} total={totals.value} /></section><section className="surface insight-warning"><div className="warning-heading"><CircleHelp size={19} /><h3>Good to know</h3></div><p>These observations use simple calculations on your saved data, not a live AI service. Always research independently or speak with a qualified professional before making financial decisions.</p></section></div></div><section className="surface chat-section"><div className="chat-intro"><div className="insight-icon"><MessageCircle size={22} /></div><div><div className="eyebrow muted-eyebrow">ASK YOUR PORTFOLIO</div><h3>InvestSphere assistant</h3><p>Ask questions and get answers grounded in your holdings.</p></div></div><div className="chat-messages" aria-live="polite">{messages.map((m, i) => <div className={`chat-bubble ${m.role}`} key={i}>{m.role === 'assistant' && <span className="chat-avatar"><Sparkles size={15} /></span>}<span>{m.text}</span></div>)}{thinking && <div className="chat-bubble assistant"><span className="chat-avatar"><Sparkles size={15} /></span><span className="typing-dots">Thinking<span>.</span><span>.</span><span>.</span></span></div>}<div ref={chatEnd} /></div><div className="suggested-questions">{['How is my portfolio performing?', 'Which investment has the highest return?', 'Show my asset allocation.'].map(q => <button key={q} onClick={() => sendMessage(q)} disabled={thinking}>{q}</button>)}</div><form className="chat-form" onSubmit={e => { e.preventDefault(); sendMessage(); }}><input value={chatInput} onChange={e => setChatInput(e.target.value)} placeholder="Ask about your portfolio..." aria-label="Ask the assistant" /><button type="submit" aria-label="Send message" disabled={!chatInput.trim() || thinking}><Send size={18} /></button></form><small className="chat-disclaimer">AI-generated information only. This is not financial advice.</small></section></>}
      {page === 'Settings' && <><PageHeading eyebrow="YOUR WORKSPACE" title="Settings" description="Manage your local data and workspace preferences." /><div className="settings-layout"><section className="surface settings-section"><div className="settings-icon"><ShieldCheck size={21} /></div><h3>Privacy by design</h3><p>Your investments, goals, transactions and watchlist are saved in this browser's local storage. Nothing is sent to a server. Clearing browser data may remove your information.</p><div className="settings-row"><div><strong>Data source</strong><span>Manually entered prices and demo watchlist quotes</span></div><span className="settings-value"><span className="status-dot" /> Local only</span></div><div className="settings-row"><div><strong>Currency</strong><span>All values are displayed in USD</span></div><span className="settings-value">USD</span></div></section><section className="surface settings-section"><div className="settings-icon"><Download size={21} /></div><h3>Your data</h3><p>Download a copy of everything you've tracked or restore the original demo workspace.</p><div className="settings-actions"><button className="outline-btn" onClick={exportData}><Download size={17} /> Export data</button><button className="outline-btn danger-btn" onClick={resetData}><Trash2 size={17} /> Reset to demo data</button></div></section><section className="surface settings-section"><div className="settings-icon"><Activity size={21} /></div><h3>About InvestSphere AI</h3><p>A personal investment tracker built to help you organize holdings, observe performance and reflect on your goals. Market information is illustrative and insights are informational only.</p><div className="settings-row"><div><strong>Version</strong><span>Personal dashboard</span></div><span className="settings-value">1.0</span></div></section></div></>}
    </div></main>
    {toast && <div className="toast" role="status"><Check size={17} />{toast}<button onClick={() => setToast('')} aria-label="Dismiss notification"><X size={15} /></button></div>}
    {modal === 'investment' && <InvestmentModal item={editing as Investment | null} onClose={closeModal} onSave={a => { setInvestments(prev => editing ? prev.map(x => x.id === a.id ? a : x) : [...prev, a]); notify(editing ? 'Investment updated' : 'Investment added to portfolio'); closeModal(); }} />}
    {modal === 'goal' && <GoalModal item={editing as Goal | null} onClose={closeModal} onSave={g => { setGoals(prev => editing ? prev.map(x => x.id === g.id ? g : x) : [...prev, g]); notify(editing ? 'Goal updated' : 'Goal created'); closeModal(); }} />}
    {modal === 'transaction' && <TransactionModal investments={investments} onClose={closeModal} onSave={(t, updated) => { setTransactions(prev => [t, ...prev]); if (updated) setInvestments(prev => updated.id ? updated.quantity === 0 ? prev.filter(x => x.id !== updated.id) : prev.map(x => x.id === updated.id ? updated : x) : [...prev, { ...updated, id: uid() }]); notify('Transaction recorded'); closeModal(); }} />}
    {modal === 'watchlist' && <Modal title="Add to watchlist" onClose={closeModal}><div className="watchlist-picker"><p>Select an asset to follow. Prices shown are demo market data.</p>{market.filter(a => !watchlist.includes(a.symbol)).map(a => <button key={a.symbol} onClick={() => { setWatchlist(prev => [...prev, a.symbol]); notify(`${a.name} added to watchlist`); closeModal(); }}><AssetIdentity name={a.name} type={a.type} subtitle={a.symbol} /><span>{money(a.price)} <Plus size={16} /></span></button>)}{market.every(a => watchlist.includes(a.symbol)) && <EmptyState icon={<Check />} title="All caught up" text="You're watching every available demo asset." />}</div></Modal>}
  </div>;
}

function PageHeading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: ReactNode }) { return <div className="page-heading"><div><div className="eyebrow muted-eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div>{action}</div>; }
function Metric({ label, value, icon, note, accent, signed }: { label: string; value: string; icon: ReactNode; note: string; accent?: boolean; signed?: number }) { return <div className={`metric ${accent ? 'metric-accent' : ''}`}><div className="metric-top"><span>{label}</span><span className="metric-icon">{icon}</span></div><strong className={signed !== undefined ? signed >= 0 ? 'positive' : 'negative' : ''}>{value}</strong><small><span className={signed !== undefined ? signed >= 0 ? 'positive' : 'negative' : ''}>{signed !== undefined ? signed >= 0 ? <ArrowUpRight size={13} /> : <ArrowDownRight size={13} /> : null}</span>{note}</small></div>; }
function AssetIdentity({ name, type, subtitle }: { name: string; type: AssetType; subtitle: string }) { return <div className="asset-identity"><span className="asset-logo" style={{ '--asset-color': colors[type] } as CSSProperties}>{name.split(' ').map(x => x[0]).slice(0, 2).join('').toUpperCase()}</span><span><strong>{name}</strong><small>{subtitle}</small></span></div>; }
function HoldingRow({ asset }: { asset: Investment }) { const ret = (asset.currentPrice / asset.buyPrice - 1) * 100; return <div className="holding-row"><AssetIdentity name={asset.name} type={asset.type} subtitle={asset.type} /><div className="holding-value"><strong>{money(asset.quantity * asset.currentPrice)}</strong><span className={ret >= 0 ? 'positive' : 'negative'}>{percent(ret)}</span></div></div>; }
function PerformanceChart({ data }: { data: { label: string; value: number }[] }) {
  return <>
    <div className="performance-chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={data} margin={{ top: 10, right: 4, left: -18, bottom: 0 }}><defs><linearGradient id="chartFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#aeea76" stopOpacity={0.22} /><stop offset="95%" stopColor="#aeea76" stopOpacity={0} /></linearGradient></defs><CartesianGrid vertical={false} stroke="#27342f" strokeDasharray="3 5" /><XAxis dataKey="label" tick={{ fill: '#77867d', fontSize: 11 }} tickLine={false} axisLine={false} minTickGap={35} dy={12} /><YAxis tickFormatter={v => compactMoney(v)} tick={{ fill: '#77867d', fontSize: 11 }} tickLine={false} axisLine={false} width={60} domain={['auto', 'auto']} /><Tooltip contentStyle={{ background: '#18241f', border: '1px solid #34453a', borderRadius: 12, color: '#ecf4e9', fontSize: 12 }} formatter={(value) => [money(Number(value)), 'Illustrative value']} labelStyle={{ color: '#a5b3a8', marginBottom: 4 }} /><Area type="monotone" dataKey="value" stroke="#b8ef80" strokeWidth={2.5} fill="url(#chartFill)" activeDot={{ r: 5, fill: '#b8ef80', stroke: '#18241f', strokeWidth: 3 }} /></AreaChart></ResponsiveContainer></div>
    <p className="chart-note">Illustrative trend only. Historical prices are not stored.</p>
  </>;
}
function AllocationChart({ allocation, total }: { allocation: { name: string; value: number; color: string }[]; total: number }) { return <>{total > 0 ? <><div className="donut-wrap"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={allocation} dataKey="value" nameKey="name" innerRadius={72} outerRadius={91} paddingAngle={3} stroke="none" isAnimationActive>{allocation.map(a => <Cell key={a.name} fill={a.color} />)}</Pie><Tooltip contentStyle={{ background: '#18241f', border: '1px solid #34453a', borderRadius: 10, color: '#ecf4e9', fontSize: 12 }} formatter={(value) => money(Number(value))} /></PieChart></ResponsiveContainer><div className="donut-center"><span>TOTAL VALUE</span><strong>{compactMoney(total)}</strong></div></div><div className="allocation-legend">{allocation.map(a => <div key={a.name}><span><i style={{ backgroundColor: a.color }} />{a.name}</span><strong>{((a.value / total) * 100).toFixed(1)}%</strong></div>)}</div></> : <EmptyState icon={<BarChart3 />} title="No allocation yet" text="Add investments to see your asset mix." />}</>; }
function InsightBlock({ icon, title, text }: { icon: ReactNode; title: string; text: string }) { return <section className="surface insight-block"><span className="insight-block-icon">{icon}</span><h3>{title}</h3><p>{text}</p></section>; }

function InvestmentModal({ item, onClose, onSave }: { item: Investment | null; onClose: () => void; onSave: (a: Investment) => void }) { const [name, setName] = useState(item?.name || ''); const [type, setType] = useState<AssetType>(item?.type || 'Stocks'); const [quantity, setQuantity] = useState(item?.quantity.toString() || ''); const [buyPrice, setBuyPrice] = useState(item?.buyPrice.toString() || ''); const [currentPrice, setCurrentPrice] = useState(item?.currentPrice.toString() || ''); const [date, setDate] = useState(item?.date || today()); const [error, setError] = useState(''); const q = Number(quantity), buy = Number(buyPrice), current = Number(currentPrice); const validNumbers = Number.isFinite(q) && q > 0 && Number.isFinite(buy) && buy > 0 && Number.isFinite(current) && current >= 0; const submit = (e: FormEvent) => { e.preventDefault(); if (!name.trim()) return setError('Enter an asset name.'); if (!validNumbers || !quantity || !buyPrice || !currentPrice) return setError('Enter a positive quantity and buy price, and a current price of zero or more.'); if (!date || date > today()) return setError('Choose a valid investment date that is not in the future.'); onSave({ id: item?.id || uid(), name: name.trim(), type, quantity: q, buyPrice: buy, currentPrice: current, date, dailyChange: item?.dailyChange || 0 }); }; return <Modal title={item ? 'Edit investment' : 'Add investment'} onClose={onClose}><form className="modal-form" onSubmit={submit}><p className="form-intro">{item ? 'Update your holding and its latest price.' : 'Add a holding to start tracking its performance.'}</p><label>Asset name<input value={name} onChange={e => setName(e.target.value)} placeholder="e.g. Apple Inc." maxLength={80} required /></label><div className="form-row"><label>Asset type<select value={type} onChange={e => setType(e.target.value as AssetType)}>{assetTypes.map(t => <option key={t}>{t}</option>)}</select></label><label>Quantity<input type="number" min="0.000001" step="any" value={quantity} onChange={e => setQuantity(e.target.value)} placeholder="0.00" required /></label></div><div className="form-row"><label>Buy price ($)<input type="number" min="0.01" step="any" value={buyPrice} onChange={e => setBuyPrice(e.target.value)} placeholder="0.00" required /></label><label>Current price ($)<input type="number" min="0" step="any" value={currentPrice} onChange={e => setCurrentPrice(e.target.value)} placeholder="0.00" required /></label></div><label>Investment date<input type="date" value={date} max={today()} onChange={e => setDate(e.target.value)} required /></label><div className="form-preview"><div><span>Invested</span><strong>{money(validNumbers ? q * buy : 0)}</strong></div><div><span>Current value</span><strong>{money(validNumbers ? q * current : 0)}</strong></div><div><span>Profit / loss</span><strong className={current - buy >= 0 ? 'positive' : 'negative'}>{money(validNumbers ? q * (current - buy) : 0)} <small>({validNumbers ? percent((current / buy - 1) * 100) : '0.00%'})</small></strong></div></div>{error && <p className="form-error" role="alert">{error}</p>}<div className="form-actions"><button type="button" className="outline-btn" onClick={onClose}>Cancel</button><button type="submit" className="primary-btn">{item ? 'Save changes' : 'Add investment'} <ArrowRight size={16} /></button></div></form></Modal>; }
function GoalModal({ item, onClose, onSave }: { item: Goal | null; onClose: () => void; onSave: (g: Goal) => void }) { const [name, setName] = useState(item?.name || ''); const [target, setTarget] = useState(item?.target.toString() || ''); const [current, setCurrent] = useState(item?.current.toString() || ''); const [date, setDate] = useState(item?.date || ''); const [error, setError] = useState(''); const submit = (e: FormEvent) => { e.preventDefault(); if (!name.trim()) return setError('Enter a goal name.'); if (!Number.isFinite(Number(target)) || Number(target) <= 0 || !Number.isFinite(Number(current)) || Number(current) < 0 || !target || !current) return setError('Enter a target above zero and a current amount of zero or more.'); if (!date || date < today()) return setError('Choose a target date today or in the future.'); onSave({ id: item?.id || uid(), name: name.trim(), target: Number(target), current: Number(current), date }); }; return <Modal title={item ? 'Edit goal' : 'Create a goal'} onClose={onClose}><form className="modal-form" onSubmit={submit}><p className="form-intro">Turn a financial milestone into something you can track.</p><label>Goal name<input value={name} onChange={e => setName(e.target.value)} placeholder="e.g. Home down payment" maxLength={70} required /></label><div className="form-row"><label>Target amount ($)<input type="number" min="0.01" step="any" value={target} onChange={e => setTarget(e.target.value)} placeholder="0.00" required /></label><label>Current amount ($)<input type="number" min="0" step="any" value={current} onChange={e => setCurrent(e.target.value)} placeholder="0.00" required /></label></div><label>Target date<input type="date" min={today()} value={date} onChange={e => setDate(e.target.value)} required /></label>{error && <p className="form-error" role="alert">{error}</p>}<div className="form-actions"><button type="button" className="outline-btn" onClick={onClose}>Cancel</button><button type="submit" className="primary-btn">{item ? 'Save changes' : 'Create goal'} <ArrowRight size={16} /></button></div></form></Modal>; }
function TransactionModal({ investments, onClose, onSave }: { investments: Investment[]; onClose: () => void; onSave: (t: Transaction, updated: Investment | null) => void }) { const [type, setType] = useState<Transaction['type']>('Buy'); const [asset, setAsset] = useState(''); const [newAsset, setNewAsset] = useState(''); const [quantity, setQuantity] = useState(''); const [price, setPrice] = useState(''); const [amount, setAmount] = useState(''); const [date, setDate] = useState(today()); const [error, setError] = useState(''); const trade = type === 'Buy' || type === 'Sell'; const cash = type === 'Deposit' || type === 'Withdrawal'; const computed = trade ? Number(quantity) * Number(price) : Number(amount); const assetName = asset === '__new' ? newAsset.trim() : asset.trim(); const submit = (e: FormEvent) => { e.preventDefault(); const q = Number(quantity), p = Number(price); if (!date || date > today()) return setError('Choose a valid date that is not in the future.'); if (trade && (!assetName || !quantity || !price || !Number.isFinite(q) || q <= 0 || !Number.isFinite(p) || p <= 0)) return setError('Enter an asset, positive quantity and positive price.'); if (type === 'Dividend' && !assetName) return setError('Enter the asset that paid the dividend.'); if (!trade && (!amount || !Number.isFinite(computed) || computed <= 0)) return setError('Enter an amount greater than zero.'); const matched = investments.find(a => a.name.toLowerCase() === assetName.toLowerCase()); if (type === 'Sell' && !matched) return setError('To sell, choose an asset currently in your portfolio.'); if (type === 'Sell' && matched && q > matched.quantity) return setError(`You only own ${matched.quantity} units of ${matched.name}.`); let updated: Investment | null = null; if (type === 'Buy' && matched) { const totalQuantity = matched.quantity + q; updated = { ...matched, quantity: totalQuantity, buyPrice: (matched.quantity * matched.buyPrice + q * p) / totalQuantity }; } else if (type === 'Buy') updated = { id: '', name: assetName, type: 'Other', quantity: q, buyPrice: p, currentPrice: p, date, dailyChange: 0 }; else if (type === 'Sell' && matched) updated = { ...matched, quantity: matched.quantity - q }; onSave({ id: uid(), date, asset: cash ? 'Cash balance' : assetName, type, quantity: trade ? q : 0, price: trade ? p : 0, amount: computed }, updated); }; return <Modal title="Record transaction" onClose={onClose}><form className="modal-form" onSubmit={submit}><p className="form-intro">Log your activity. Buy and sell trades update matching holdings.</p><label>Transaction type<select value={type} onChange={e => { setType(e.target.value as Transaction['type']); setError(''); }}><option>Buy</option><option>Sell</option><option>Deposit</option><option>Withdrawal</option><option>Dividend</option></select></label>{!cash && <label>Asset name{trade && investments.length > 0 ? <select value={asset} onChange={e => setAsset(e.target.value)} required><option value="">Select an asset</option>{investments.map(a => <option key={a.id} value={a.name}>{a.name}</option>)}{type === 'Buy' && <option value="__new">+ New asset</option>}</select> : <input value={asset} onChange={e => setAsset(e.target.value)} placeholder="e.g. Apple Inc." required />}</label>}{type === 'Buy' && asset === '__new' && <label>New asset name<input value={newAsset} onChange={e => setNewAsset(e.target.value)} placeholder="Enter asset name" maxLength={80} required /></label>}{trade ? <div className="form-row"><label>Quantity<input type="number" min="0.000001" step="any" value={quantity} onChange={e => setQuantity(e.target.value)} placeholder="0.00" required /></label><label>Price per unit ($)<input type="number" min="0.01" step="any" value={price} onChange={e => setPrice(e.target.value)} placeholder="0.00" required /></label></div> : <label>Amount ($)<input type="number" min="0.01" step="any" value={amount} onChange={e => setAmount(e.target.value)} placeholder="0.00" required /></label>}<label>Date<input type="date" value={date} max={today()} onChange={e => setDate(e.target.value)} required /></label><div className="transaction-preview"><span>Transaction amount</span><strong>{money(Number.isFinite(computed) && computed > 0 ? computed : 0)}</strong></div>{type === 'Buy' && <p className="form-hint">Newly purchased assets are added as "Other". Edit the holding afterward to set its asset type and current price.</p>}{error && <p className="form-error" role="alert">{error}</p>}<div className="form-actions"><button type="button" className="outline-btn" onClick={onClose}>Cancel</button><button type="submit" className="primary-btn">Record transaction <ArrowRight size={16} /></button></div></form></Modal>; }

export default App;